    33	function getInitialCurrentDateView(value: Date | string, minDate: Date, maxDate: Date) {
    34	    let initialCurrentDateView = typeof value === 'string' ? parseISO(value) : new Date(value);
    35	
    36	    if (maxDate < initialCurrentDateView) {
    37	        initialCurrentDateView = maxDate;
    38	    } else if (minDate > initialCurrentDateView) {
    39	        initialCurrentDateView = minDate;
    40	    }
    41	
    42	    return initialCurrentDateView;
    43	}
