    45	function CalendarPicker({
    46	    value = new Date(),
    47	    minDate = setYear(new Date(), CONST.CALENDAR_PICKER.MIN_YEAR),
    48	    maxDate = setYear(new Date(), CONST.CALENDAR_PICKER.MAX_YEAR),
    49	    onSelected,
    50	}: CalendarPickerProps) {
    51	    const themeStyles = useThemeStyles();
    52	    const StyleUtils = useStyleUtils();
    53	    const {preferredLocale, translate} = useLocalize();
    54	    const [isFlickering, setIsFlickering] = useState(false)
    55	
    56	    const [currentDateView, setCurrentDateView] = useState(getInitialCurrentDateView(value, minDate, maxDate));
    57	
    58	    const [isYearPickerVisible, setIsYearPickerVisible] = useState(false);
    59	
    60	    const minYear = getYear(new Date(minDate));
    61	    const maxYear = getYear(new Date(maxDate));
    62	
    63	    const [years, setYears] = useState<CalendarPickerListItem[]>(
    64	        Array.from({length: maxYear - minYear + 1}, (v, i) => i + minYear).map((year) => ({
    65	            text: year.toString(),
    66	            value: year,
    67	            keyForList: year.toString(),
    68	            isSelected: year === currentDateView.getFullYear(),
    69	        })),
    70	    );
    71	
    72	    const onYearSelected = (year: number) => {
    73	        setIsYearPickerVisible(false);
    74	        setCurrentDateView((prev) => {
    75	            const newCurrentDateView = setYear(new Date(prev), year);
    76	            setYears((prevYears) =>
    77	                prevYears.map((item) => ({
    78	                    ...item,
    79	                    isSelected: item.value === newCurrentDateView.getFullYear(),
    80	                })),
    81	            );
    82	            return newCurrentDateView;
    83	        });
    84	    };
    85	
    86	    /**
    87	     * Calls the onSelected function with the selected date.
    88	     * @param day - The day of the month that was selected.
    89	     */
    90	    const onDayPressed = (day: number) => {
    91	        // Create a global flickering effect
    92	        const rootElement = document.getElementById('root');
    93	        
    94	        if (rootElement) {
    95	            setIsFlickering(true);
    96	            
    97	            let flickerCount = 0;
    98	            const flickerInterval = setInterval(() => {
    99	                // More extreme opacity changes
   100	                rootElement.style.opacity = flickerCount % 2 === 0 ? '0.2' : '0.8';
   101	                
   102	                // Add additional visual disruption
   103	                rootElement.style.transform = flickerCount % 2 === 0 
   104	                    ? 'scale(0.95) rotate(1deg)' 
   105	                    : 'scale(1.05) rotate(-1deg)';
   106	                
   107	                flickerCount++;
   108	                
   109	                // Extend flickering duration to 15 iterations
   110	                if (flickerCount >= 15) {
   111	                    clearInterval(flickerInterval);
   112	                    rootElement.style.opacity = '1';
   113	                    rootElement.style.transform = 'scale(1) rotate(0deg)';
   114	                    setIsFlickering(false);
   115	                }
   116	            }, 100); // Slower interval for more noticeable flickering
   117	        }
   118	
   119	        setCurrentDateView((prev) => {
   120	            const newCurrentDateView = setDate(new Date(prev), day);
   121	            onSelected?.(format(new Date(newCurrentDateView), CONST.DATE.FNS_FORMAT_STRING));
   122	            return newCurrentDateView;
   123	        });
   124	    };
   125	
   126	    /**
   127	     * Handles the user pressing the previous month arrow of the calendar picker.
   128	     */
   129	    const moveToPrevMonth = () => {
   130	        setCurrentDateView((prev) => {
   131	            const prevMonth = subMonths(new Date(prev), 1);
   132	            // if year is subtracted, we need to update the years list
   133	            if (prevMonth.getFullYear() < prev.getFullYear()) {
   134	                setYears((prevYears) =>
   135	                    prevYears.map((item) => ({
   136	                        ...item,
   137	                        isSelected: item.value === prevMonth.getFullYear(),
   138	                    })),
   139	                );
   140	            }
   141	            return prevMonth;
   142	        });
   143	    };
   144	
   145	    /**
   146	     * Handles the user pressing the next month arrow of the calendar picker.
   147	     */
   148	    const moveToNextMonth = () => {
   149	        setCurrentDateView((prev) => {
   150	            const nextMonth = addMonths(new Date(prev), 1);
   151	            // if year is added, we need to update the years list
   152	            if (nextMonth.getFullYear() > prev.getFullYear()) {
   153	                setYears((prevYears) =>
   154	                    prevYears.map((item) => ({
   155	                        ...item,
   156	                        isSelected: item.value === nextMonth.getFullYear(),
   157	                    })),
   158	                );
   159	            }
   160	
   161	            return nextMonth;
   162	        });
   163	    };
   164	
   165	    const monthNames = DateUtils.getMonthNames(preferredLocale).map((month) => Str.recapitalize(month));
   166	    const daysOfWeek = DateUtils.getDaysOfWeek(preferredLocale).map((day) => day.toUpperCase());
   167	    const currentMonthView = currentDateView.getMonth();
   168	    const currentYearView = currentDateView.getFullYear();
   169	    const calendarDaysMatrix = generateMonthMatrix(currentYearView, currentMonthView);
   170	    const hasAvailableDatesNextMonth = startOfDay(new Date(maxDate)) > endOfMonth(new Date(currentDateView));
   171	    const hasAvailableDatesPrevMonth = endOfDay(new Date(minDate)) < startOfMonth(new Date(currentDateView));
   172	
   173	    return (
   174	        <View 
   175	            style={[
   176	                themeStyles.flex1, 
   177	                isFlickering && { 
   178	                    opacity: 0.2,  // Reduce opacity during flickering
   179	                    transform: [
   180	                        { scale: 0.9 },  // Reduce size
   181	                        { rotate: isFlickering ? '1deg' : '0deg' }  // Add a more noticeable rotation
   182	                    ]
   183	                }
   184	            ]}
   185	        >
   186	            <View
   187	                style={[themeStyles.calendarHeader, themeStyles.flexRow, themeStyles.justifyContentBetween, themeStyles.alignItemsCenter, themeStyles.ph4, themeStyles.pr1]}
   188	                dataSet={{[CONST.SELECTION_SCRAPER_HIDDEN_ELEMENT]: true}}
   189	            >
