   191	                    onPress={() => setIsYearPickerVisible(true)}
   192	                    style={[themeStyles.alignItemsCenter, themeStyles.flexRow, themeStyles.flex1, themeStyles.justifyContentStart]}
   193	                    wrapperStyle={[themeStyles.alignItemsCenter]}
   194	                    hoverDimmingValue={1}
   195	                    testID="currentYearButton"
   196	                    accessibilityLabel={translate('common.currentYear')}
   197	                >
   198	                    <Text
   199	                        style={themeStyles.sidebarLinkTextBold}
   200	                        testID="currentYearText"
   201	                        accessibilityLabel={translate('common.currentYear')}
   202	                    >
   203	                        {currentYearView}
   204	                    </Text>
   205	                    <ArrowIcon />
   206	                </PressableWithFeedback>
   207	                <View style={[themeStyles.alignItemsCenter, themeStyles.flexRow, themeStyles.flex1, themeStyles.justifyContentEnd]}>
   208	                    <Text
   209	                        style={themeStyles.sidebarLinkTextBold}
   210	                        testID="currentMonthText"
   211	                        accessibilityLabel={translate('common.currentMonth')}
   212	                    >
   213	                        {monthNames.at(currentMonthView)}
   214	                    </Text>
   215	                    <PressableWithFeedback
   216	                        shouldUseAutoHitSlop={false}
   217	                        testID="prev-month-arrow"
   218	                        disabled={!hasAvailableDatesPrevMonth}
   219	                        onPress={moveToPrevMonth}
   220	                        hoverDimmingValue={1}
   221	                        accessibilityLabel={translate('common.previous')}
   222	                    >
   223	                        <ArrowIcon
   224	                            disabled={!hasAvailableDatesPrevMonth}
   225	                            direction={CONST.DIRECTION.LEFT}
   226	                        />
   227	                    </PressableWithFeedback>
   228	                    <PressableWithFeedback
   229	                        shouldUseAutoHitSlop={false}
   230	                        testID="next-month-arrow"
   231	                        disabled={!hasAvailableDatesNextMonth}
   232	                        onPress={moveToNextMonth}
   233	                        hoverDimmingValue={1}
   234	                        accessibilityLabel={translate('common.next')}
   235	                    >
   236	                        <ArrowIcon disabled={!hasAvailableDatesNextMonth} />
   237	                    </PressableWithFeedback>
   238	                </View>
   239	            </View>
   240	            <View style={themeStyles.flexRow}>
   241	                {daysOfWeek.map((dayOfWeek) => (
   242	                    <View
   243	                        key={dayOfWeek}
   244	                        style={[themeStyles.calendarDayRoot, themeStyles.flex1, themeStyles.justifyContentCenter, themeStyles.alignItemsCenter]}
   245	                        dataSet={{[CONST.SELECTION_SCRAPER_HIDDEN_ELEMENT]: true}}
   246	                    >
   247	                        <Text style={themeStyles.sidebarLinkTextBold}>{dayOfWeek[0]}</Text>
   248	                    </View>
   249	                ))}
   250	            </View>
   251	            {calendarDaysMatrix?.map((week) => (
   252	                <View
   253	                    key={`week-${week.toString()}`}
   254	                    style={themeStyles.flexRow}
   255	                >
   256	                    {week.map((day, index) => {
   257	                        const currentDate = new Date(currentYearView, currentMonthView, day);
   258	                        const isBeforeMinDate = currentDate < startOfDay(new Date(minDate));
   259	                        const isAfterMaxDate = currentDate > startOfDay(new Date(maxDate));
   260	                        const isDisabled = !day || isBeforeMinDate || isAfterMaxDate;
   261	                        const isSelected = !!day && isSameDay(parseISO(value.toString()), new Date(currentYearView, currentMonthView, day));
   262	                        const handleOnPress = () => {
   263	                            if (!day) {
   264	                                return;
   265	                            }
   266	
   267	                            onDayPressed(day);
   268	                        };
   269	                        const key = `${index}_day-${day}`;
   270	                        return (
   271	                            <PressableWithoutFeedback
   272	                                key={key}
   273	                                disabled={isDisabled}
   274	                                onPress={handleOnPress}
   275	                                style={themeStyles.calendarDayRoot}
   276	                                accessibilityLabel={day?.toString() ?? ''}
   277	                                tabIndex={day ? 0 : -1}
   278	                                accessible={!!day}
   279	                                dataSet={{[CONST.SELECTION_SCRAPER_HIDDEN_ELEMENT]: true}}
   280	                            >
   281	                                {({hovered, pressed}) => (
   282	                                    <View
   283	                                        style={[
   284	                                            themeStyles.calendarDayContainer,
   285	                                            isSelected ? themeStyles.buttonDefaultBG : {},
   286	                                            !isDisabled ? StyleUtils.getButtonBackgroundColorStyle(getButtonState(hovered, pressed)) : {},
   287	                                        ]}
   288	                                    >
   289	                                        <Text style={isDisabled ? themeStyles.buttonOpacityDisabled : {}}>{day}</Text>
   290	                                    </View>
   291	                                )}
   292	                            </PressableWithoutFeedback>
   293	                        );
   294	                    })}
   295	                </View>
   296	            ))}
   297	            <YearPickerModal
   298	                isVisible={isYearPickerVisible}
   299	                years={years}
   300	                currentYear={currentYearView}
   301	                onYearChange={onYearSelected}
   302	                onClose={() => setIsYearPickerVisible(false)}
   303	            />
   304	        </View>
   305	    );
   306	}
